/* From Uiverse.io by Akshdeep74644 - Tags: input */
.__UIV_SCOPE__ .container {
  position: relative;
  width: 200px;
}

.__UIV_SCOPE__ .container input {
  width: 100%;
  background: transparent;
  outline: none;
  border: none;
  color: #222;
  padding: 8px;
}

.__UIV_SCOPE__ .container label {
  position: absolute;
  left: 0;
  top: 0;
  color: rgba(105, 105, 105, 0.7);
  text-transform: uppercase;
  pointer-events: none;
  transition: .5s;
  font-weight: bold;
}

.__UIV_SCOPE__ .container input:valid ~ label,
.__UIV_SCOPE__ .container input:focus ~ label {
  color: rgb(10, 131, 212);
  transform: translateY(-15px);
  font-size: .6rem;
}

.__UIV_SCOPE__ .container i {
  position: absolute;
  left: 0;
  bottom: 0;
  width: 100%;
  height: 2px;
  background: #222;
}

.__UIV_SCOPE__ .container i:before {
  content: '';
  position: absolute;
  width: 100%;
  height: 100%;
  background: linear-gradient(90deg, #ff1b69, #ff0, #2196f3, #9c27b0, #ff1b69);
  animation: animate 3s linear infinite;
}
